"""
AntonioOliveiraCalc - AUTO-EXTRATOR (bundle self-contained)
===========================================================
Baixe SO este arquivo, jogue na pasta destino e rode:

    python AntonioOliveiraCalc_bundle.py

Escreve todos os arquivos do add-in na pasta atual (ou passe outra pasta como
argumento). Os .py + o .csv precisam ficar no PYTHONPATH que o .xlam PROD
espera: Z:/AntonioOliveira/AntonioOliveiraCalc (baked no .xlam, com barra
invertida). Se a share do banco tiver outro caminho, o .xlam precisa ser
re-baked com o path certo.

Todas as UDFs tem prefixo cp (=cpPu, =cpTaxa, =cpVna, =cpFluxo, =cpSelic ...).
Sem dependencias externas (so a stdlib). Nao contem segredos.
"""
import base64, os, sys

DEST = sys.argv[1] if len(sys.argv) > 1 else os.path.dirname(os.path.abspath(__file__))

FILES = {
    'AntonioOliveiraCalc.xlam': '',
    'AntonioOliveiraCalc.py': '',
    'apis.py': '',
    'config.py': '',
    'di.py': '',
    'feriados_anbima.csv': '',
    'CLAUDE.md': '',
    'LEIA-ME.md': '',
    'INSTALAR_NO_BANCO.md': '',
    'CONFIGURAR_PYTHON.md': '',
    'DIAGNOSTICO_DLL.md': '',
}

def main():
    os.makedirs(DEST, exist_ok=True)
    for nome, b64 in FILES.items():
        with open(os.path.join(DEST, nome), "wb") as fh:
            fh.write(base64.b64decode(b64))
        print("escrito:", nome)
    print(str(len(FILES)) + " arquivos extraidos em " + DEST)

if __name__ == "__main__":
    main()
